import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNext()) return;

        String s = sc.next();

        boolean[][] seen = new boolean[4][14];
        boolean[] duplicate = new boolean[4];

        for (int i = 0; i + 2 < s.length(); i += 3) {
            int value = (s.charAt(i) - '0') * 10 + (s.charAt(i + 1) - '0');
            char suit = s.charAt(i + 2);

            int idx = 0;
            if (suit == 'C') idx = 0;
            else if (suit == 'E') idx = 1;
            else if (suit == 'U') idx = 2;
            else if (suit == 'P') idx = 3;

            if (seen[idx][value]) {
                duplicate[idx] = true;
            } else {
                seen[idx][value] = true;
            }
        }

        StringBuilder sb = new StringBuilder();

        for (int suit = 0; suit < 4; suit++) {
            if (duplicate[suit]) {
                sb.append("erro");
            } else {
                int present = 0;
                for (int v = 1; v <= 13; v++) {
                    if (seen[suit][v]) present++;
                }
                sb.append(13 - present);
            }
            sb.append('\n');
        }

        System.out.print(sb.toString());
    }
}
